\operatorname{BSub}_{M}(y,E,x,N)=
\begin{cases}
E,&y=x,\\
E[x:=N],&y\ne x\ \wedge\ y\notin\operatorname{FV}_{M}(N),\\
(E[y:=z])[x:=N],&y\ne x\ \wedge\ y\in\operatorname{FV}_{M}(N),
\end{cases}

\mathsf{TreeDom}_{M}
:=\{D\subseteq\mathbb N^{<\omega}:D\ne\varnothing,\
D\text{ 有限、前缀封闭且子索引连续}\},

\mathsf{Rule}_{M,\to}
=
\{((\Delta;\Gamma,x:A\vdash M:B),\Delta;\Gamma\vdash\lambda x.M:A\to B)\}
\cup
\{((\Delta;\Gamma\vdash M:A\to B,\Delta;\Gamma\vdash N:A),\Delta;\Gamma\vdash MN:B)\},

\mathsf{Rule}_{M,\times}
=
\{((\Delta;\Gamma\vdash M:A,\Delta;\Gamma\vdash N:B),\Delta;\Gamma\vdash\langle M,N\rangle:A\times B)\}
\cup
\{((\Delta;\Gamma\vdash P:A\times B),\Delta;\Gamma\vdash\pi_1(P):A)\}
\cup
\{((\Delta;\Gamma\vdash P:A\times B),\Delta;\Gamma\vdash\pi_2(P):B)\},
